def coconut_answer(model, question_ids, n_thoughts):
    embeds = model.embed(question_ids + [BOT])
    out = model(inputs_embeds=embeds)
    h = out.last_hidden[-1]          # thought 1
    for k in range(n_thoughts - 1):
        embeds = concat(embeds, h)   # vector, not a token
        out = model(inputs_embeds=embeds)
        h = out.last_hidden[-1]      # next thought
    embeds = concat(embeds, h, model.embed([EOT]))
    return model.generate(inputs_embeds=embeds)
